  "range_high": 0.28,
  "summary": [
    "Bayesian posterior probability for Frontier Group Holdings filing bankruptcy before 2026-05-01 is 21% after anchoring to the ULCC distress reference class and applying updates.",
    "Near-term liquidity remains solid and debt maturities extend beyond 2027, which lowers near-term bankruptcy risk.",
    "Distress signals from Altman Z-score and sector-wide pressures (Spirit Airlines context) push risk higher, creating non-negligible tail risk.",
    "Overall, the calibrated estimate remains low but non-negligible, reflecting a balance of mitigants and industry stress."
  ],
  "confidence": "medium",
  "narrative": "Starting from a ULCC distress anchor, strong liquidity and the Verizon transaction reduce near-term bankruptcy risk, but a distressed Altman Z-score and sector pressures keep the probability non-trivial. The posterior probability is calibrated to 0.21 with a modest uncertainty range to reflect remaining macro and industry dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class: ULCCs with high debt and distressed Altman Z-score; anchor probability reflects base-rate within this class prior to applying updates."
    },
    "factor_updates": [
      {
        "factor": "Verizon acquisition closure (January 2026)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Transaction closing reduces standalone bankruptcy risk by integrating Frontier and removing near-term insolvency catalysts."
      },
      {
        "factor": "Near-term liquidity and debt maturities",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Reported liquidity (~$2.6B) and debt maturities not before 2027 lower near-term distress probability."
      },
      {
        "factor": "Distress signals from Altman Z-score",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Z ≈ 0.38 indicates bankruptcy risk per Altman framework, elevating the hazard relative to the anchor."
      },
      {
        "factor": "Industry sector pressures (Spirit Airlines bankruptcy context)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Sector distress and contagion risk add to Frontier's risk profile even as individual liquidity remains solid."
      },
      {
        "factor": "Undrawn revolving credit facility",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Undrawn $205M facility provides liquidity runway, mitigating near-term default risk."
      }
    ],
    "synthesis_rationale": "Starting from a moderate base-rate anchor, the strongest near-term mitigants (Verizon deal and liquidity) offset several distress signals, but persistent leverage, debt-maturities risk, and sector distress prevent the posterior from collapsing. The 21% posterior reflects calibrated weighting of these factors with a modest calibration adjustment toward the lower tail, acknowledging uncertainty around merger outcomes and macro conditions."
  }
}

