    "factor_updates": [
      {
        "factor": "Verizon acquisition closure (January 2026)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Regulatory and strategic closure would remove standalone bankruptcy risk in the near term, reducing the baseline probability."
      },
