        "magnitude": "moderate",
        "rationale": "Quarterly losses and profitability headwinds in a stressed ULCC environment raise default risk if liquidity or credit conditions tighten."
      },
      {
        "factor": "Secured liquidity facilities (e.g., $205 million revolver)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Undrawn revolver and liquidity facilities extend runway, mitigating near-term default risk and supporting refinancing capacity."
      }
